import 'dart:convert';
import 'dart:io';
import 'package:crypto/crypto.dart';
import 'terminal_glb.dart';

/// Owns generated files only. Native calls must have returned and their outputs
/// passed the artifact gate before stageValidated is called. A preview enqueue
/// is not a read acknowledgement: hold its lease through the actual async read.
final class GeneratedArtifactRetirement {
  GeneratedArtifactRetirement({
    required this.root,
    required this.evidenceFile,
    Future<void> Function(File)? deleteFile,
  }) : _deleteFile = deleteFile ?? _delete;
  final Directory root;
  final File evidenceFile;
  final Future<void> Function(File) _deleteFile;
  final _files = <String, _Artifact>{};
  final _leases = <String, Set<Object>>{};
  final deleted = <String>[];
  final failures = <String>[];
  int _validated = -1;
  bool _finalized = false;
  bool _sealed = false;
  Future<void> _retiring = Future<void>.value();
  static Future<void> _delete(File file) async {
    await file.delete();
  }

  static Future<String> _hash(File f) async =>
      (await sha256.bind(f.openRead()).first).toString();
  String _path(String relative) {
    if (!root.path.startsWith('/') ||
        root.path == '/' ||
        relative.isEmpty ||
        relative.startsWith('/') ||
        relative.contains('\\') ||
        relative.contains('\u0000') ||
        relative.split('/').any((p) => p.isEmpty || p == '.' || p == '..')) {
      throw StateError(
        'Retirement path outside generated ownership: $relative',
      );
    }
    return '${root.path}/$relative';
  }

  void register(
    String relative, {
    required int bytes,
    required String sha256,
    required int lastReaderStage,
  }) {
    _path(relative);
    if (_finalized ||
        bytes < 0 ||
        !RegExp(r'^[0-9a-f]{64}$').hasMatch(sha256) ||
        lastReaderStage < 0 ||
        _files.containsKey(relative)) {
      throw StateError(
        'Invalid or duplicate generated retirement identity: $relative',
      );
    }
    _files[relative] = _Artifact(bytes, sha256, lastReaderStage);
  }

  GeneratedArtifactLease acquireLease(String relative, String consumer) {
    _path(relative);
    if (!_files.containsKey(relative) ||
        deleted.contains(relative) ||
        consumer.isEmpty ||
        _finalized) {
      throw StateError('Lease requires live generated artifact: $relative');
    }
    final token = Object();
    (_leases[relative] ??= {}).add(token);
    return GeneratedArtifactLease._(() async {
      _leases[relative]?.remove(token);
      await retireReady();
    });
  }

  Future<void> _canonicalRootAndEvidence() async {
    if (await root.resolveSymbolicLinks() != root.path ||
        evidenceFile.path.startsWith('${root.path}/')) {
      throw StateError(
        'Retirement requires canonical root and external evidence',
      );
    }
    final evidencePath = evidenceFile.path;
    if (!evidencePath.startsWith('/') ||
        evidencePath.contains('\\') ||
        evidencePath.contains('\u0000') ||
        evidencePath
            .substring(1)
            .split('/')
            .any((p) => p.isEmpty || p == '.' || p == '..')) {
      throw StateError('Invalid retirement evidence path');
    }
    var current = '';
    for (final part in evidenceFile.parent.path.substring(1).split('/')) {
      current = '$current/$part';
      final kind = await FileSystemEntity.type(current, followLinks: false);
      if (kind == FileSystemEntityType.notFound)
        await Directory(current).create();
      else if (kind != FileSystemEntityType.directory)
        throw StateError('Noncanonical retirement evidence parent');
      if (await Directory(current).resolveSymbolicLinks() != current)
        throw StateError('Noncanonical retirement evidence parent');
    }
    final evidenceKind = await FileSystemEntity.type(
      evidencePath,
      followLinks: false,
    );
    if (evidenceKind != FileSystemEntityType.notFound &&
        evidenceKind != FileSystemEntityType.file) {
      throw StateError('Noncanonical retirement evidence');
    }
  }

  Future<File> _regular(String relative) async {
    await _canonicalRootAndEvidence();
    final path = _path(relative);
    if (await FileSystemEntity.type(path, followLinks: false) !=
            FileSystemEntityType.file ||
        await File(path).resolveSymbolicLinks() != path) {
      throw StateError('Noncanonical generated file retained: $relative');
    }
    return File(path);
  }

  Future<void> _verify(String relative) async {
    final f = await _regular(relative), spec = _files[relative]!;
    if (await f.length() != spec.bytes || await _hash(f) != spec.hash) {
      throw StateError('Generated bytes changed; retained: $relative');
    }
  }

  Future<void> _evidence(String status) async {
    await _canonicalRootAndEvidence();
    await evidenceFile.writeAsString(
      jsonEncode({
        'schema': 'PW38_GENERATED_RETIREMENT_V1',
        'root': root.path,
        'status': status,
        'validated_stage': _validated,
        'deleted': deleted,
        'failures': failures,
        'active_leases': {
          for (final e in _leases.entries)
            if (e.value.isNotEmpty) e.key: e.value.length,
        },
        'artifacts': {
          for (final e in _files.entries)
            e.key: {
              'bytes': e.value.bytes,
              'sha256': e.value.hash,
              'last_reader_stage': e.value.lastReader,
            },
        },
      }),
      flush: true,
    );
  }

  Future<void> stageValidated(int stage) async {
    if (stage < _validated || stage > 12)
      throw StateError('Invalid validated retirement stage');
    _validated = stage;
    await retireReady();
  }

  Future<void> seal() async {
    _sealed = true;
    await _retiring;
  }

  Future<void> retireReady() =>
      _retiring = _retiring.then((_) => _retireReady());
  Future<void> _retireReady() async {
    if (_finalized || _sealed) return;
    try {
      final ready = _files.keys
          .where(
            (p) =>
                !deleted.contains(p) &&
                _files[p]!.lastReader <= _validated &&
                (_leases[p]?.isEmpty ?? true),
          )
          .toList();
      // Preflight every candidate before the first deletion.
      for (final p in ready) {
        await _verify(p);
      }
      await _evidence('RETIRING');
      for (final p in ready) {
        await _verify(p);
        await _deleteFile(File(_path(p)));
        if (await FileSystemEntity.type(_path(p), followLinks: false) !=
            FileSystemEntityType.notFound)
          throw StateError('Delete did not remove $p');
        deleted.add(p);
        await _evidence('RETIRING');
      }
      await _evidence('STAGE_RETIRED');
    } catch (e) {
      failures.add('$e');
      try {
        await _evidence('STOPPED');
      } catch (evidenceError) {
        failures.add('Evidence persistence: $evidenceError');
      }
      rethrow;
    }
  }

  /// Invoke only after GLB format/readback and record publication checks pass.
  /// Caller supplies the real validator, never a receipt boolean. All reads and
  /// consumer leases must be finished. Inventory never follows symlinks and no
  /// recursive delete is used, even within this exclusive generated root.
  Future<void> finalizeGlbOnly({
    required String glbRelative,
    required String publishedPath,
    required Future<void> Function() validatePublished,
  }) async {
    await _canonicalRootAndEvidence();
    final spec = _files[glbRelative];
    if (spec == null ||
        !glbRelative.endsWith('.glb') ||
        _leases.values.any((l) => l.isNotEmpty))
      throw StateError('Final GLB or consumers not ready');
    await _verify(glbRelative);
    final published = File(publishedPath);
    if (publishedPath.startsWith('${root.path}/') ||
        await published.resolveSymbolicLinks() != publishedPath ||
        await FileSystemEntity.type(publishedPath, followLinks: false) !=
            FileSystemEntityType.file ||
        await published.length() != spec.bytes ||
        await _hash(published) != spec.hash)
      throw StateError('GLB publication readback mismatch');
    await validateTerminalGlb(await _regular(glbRelative));
    await validateTerminalGlb(published);
    await validatePublished();
    final files = <String>[], directories = <Directory>[];
    await for (final e in root.list(recursive: true, followLinks: false)) {
      final relative = e.path.substring(root.path.length + 1);
      if (await e.resolveSymbolicLinks() != e.path || e is Link)
        throw StateError('Ambiguous final generated ownership: $relative');
      if (e is Directory) {
        directories.add(e);
      } else if (e is File) {
        if (relative == glbRelative) continue;
        files.add(relative);
        if (!_files.containsKey(relative))
          register(
            relative,
            bytes: await e.length(),
            sha256: await _hash(e),
            lastReaderStage: 12,
          );
      } else {
        throw StateError('Unknown generated entity: $relative');
      }
    }
    // Keep the GLB registered at a stage beyond final cleanup.
    _files[glbRelative] = _Artifact(spec.bytes, spec.hash, 99);
    await stageValidated(12);
    directories.sort((a, b) => b.path.length.compareTo(a.path.length));
    for (final d in directories) {
      if (await d.list(followLinks: false).isEmpty) await d.delete();
    }
    final remaining = await root
        .list(recursive: true, followLinks: false)
        .where((e) => e is! Directory)
        .map((e) => e.path)
        .toList();
    if (remaining.length != 1 || remaining.single != _path(glbRelative))
      throw StateError('Generated workspace is not GLB-only');
    _finalized = true;
    await _evidence('GLB_ONLY');
  }
}

final class GeneratedArtifactLease {
  GeneratedArtifactLease._(this._release);
  final Future<void> Function() _release;
  bool _released = false;
  Future<void> release() async {
    if (!_released) {
      _released = true;
      await _release();
    }
  }
}

final class _Artifact {
  _Artifact(this.bytes, this.hash, this.lastReader);
  final int bytes, lastReader;
  final String hash;
}
